function binarySearch(list, target) {
  let low = 0;
  let high = list.length - 1;
  while (low <= high) {
    const middle = Math.floor((low + high) / 2);
    if (list[middle] === target) return middle;
    if (list[middle] < target) low = middle + 1;
    else high = middle - 1;
  }
  return -1;
}
